(() => {
  'use strict';

  const host = window.parent || window;
  const source = 'https://testingcf.jsdelivr.net/gh/jerinmiss620-web/Freesia-Communicator@main/core/current/Freesia-Messenger.js?t=' + Date.now();

  import(source).then(() => {
    const instance = host.__FREESIA_MESSENGER_V1__;
    if (!instance?.version || instance.hostWindow !== host) {
      throw new Error('远程源码已下载，但通讯侠实例没有成功注册。');
    }
    console.info('[Freesia Messenger] GitHub 直连加载成功，当前版本 v' + instance.version);
  }).catch(error => {
    const message = String(error?.message || error);
    console.error('[Freesia Messenger] GitHub 直连加载失败：', error);
    try { host.toastr?.error?.('GitHub 直连加载失败：' + message.slice(0, 180), '通讯侠'); } catch {}
  });
})();
